use clap::{ArgGroup, Parser, Subcommand};
use language_lab::{invalid, Database, Filters, Result, Review};
use std::{io::Read, path::PathBuf};
#[derive(Parser)]
#[command(
    version,
    about = "Persistent learning records and calendar-based review scheduling"
)]
struct Cli {
    #[arg(long, global = true)]
    db: Option<PathBuf>,
    #[arg(long, global = true)]
    language: Option<String>,
    #[command(subcommand)]
    command: Command,
}
#[derive(Subcommand)]
enum Command {
    /// Create a new database without overwriting existing files.
    Init {
        path: PathBuf,
        #[arg(long)]
        timezone: String,
    },
    /// Read the current clock, languages, pinned records, due reviews and recent records.
    Context {
        #[arg(long, default_value_t = 20)]
        limit: usize,
    },
    /// Retrieve exact IDs, including historical records.
    Get {
        #[arg(required=true,num_args=1..)]
        ids: Vec<String>,
    },
    /// Query active or retired records.
    List {
        #[arg(long, conflicts_with = "retired")]
        due: bool,
        #[arg(long)]
        retired: bool,
        #[arg(long)]
        since: Option<String>,
        #[arg(long)]
        search: Option<String>,
        #[arg(long, default_value_t = 20)]
        limit: usize,
        #[arg(long)]
        cursor: Option<String>,
    },
    /// Atomically create, replace, split, merge or retire records from JSON. Use - for stdin.
    Replace {
        #[arg(long)]
        file: PathBuf,
    },
    /// Set or clear the pending review for active records.
    #[command(group(ArgGroup::new("mode").required(true).args(["in_days","on","clear"])))]
    Schedule {
        #[arg(required=true,num_args=1..)]
        ids: Vec<String>,
        #[arg(long)]
        in_days: Option<u64>,
        #[arg(long)]
        on: Option<String>,
        #[arg(long)]
        clear: bool,
    },
}

fn check_limit(n: usize) -> Result<()> {
    if !(1..=1000).contains(&n) {
        Err(invalid("limit must be 1..1000"))
    } else {
        Ok(())
    }
}

pub fn context(&self, lang: Option<&str>, limit: usize) -> Result<Value> {
    check_limit(limit)?;
    if let Some(lang) = lang {
        language(lang)?;
    }
    let mut stmt = self
        .conn
        .prepare("SELECT DISTINCT language FROM records ORDER BY language")?;
    let languages = stmt
        .query_map([], |r| r.get::<_, String>(0))?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let mut result = json!({"now":self.now.to_rfc3339_opts(chrono::SecondsFormat::Nanos,true),"today":self.today().to_string(),"timezone":self.timezone.to_string(),"languages":languages});
    if let Some(lang) = lang {
        let mut pinned = self
            .all(lang)?
            .into_iter()
            .filter(|r| r.pinned && r.retired_at.is_none())
            .collect::<Vec<_>>();
        pinned.sort_by(|a, b| b.created_at.cmp(&a.created_at).then(a.id.cmp(&b.id)));
        result["language"] = json!(lang);
        result["pinned"] = json!(pinned);
        result["due"] = self.list(
            lang,
            Filters {
                due: true,
                ..Default::default()
            },
            limit,
            None,
        )?;
        result["recent"] = self.list(lang, Filters::default(), limit, None)?;
    }
    Ok(result)
}

pub fn list(
    &self,
    lang: &str,
    filters: Filters,
    limit: usize,
    cursor: Option<&str>,
) -> Result<Value> {
    language(lang)?;
    check_limit(limit)?;
    if filters.due && filters.retired {
        return Err(invalid("due and retired are incompatible"));
    }
    let since = filters.since.as_deref().map(date).transpose()?;
    let (cutoff, offset) = if let Some(token) = cursor {
        let c: Cursor = serde_json::from_str(token).map_err(|_| invalid("malformed cursor"))?;
        if c.database != self.identity || c.language != lang || c.filters != filters {
            return Err(invalid("cursor database, language, or filters differ"));
        }
        (date(&c.cutoff)?, c.offset)
    } else {
        (self.today(), 0)
    };
    let mut records = self.all(lang)?;
    records.retain(|r| {
        let active = r.retired_at.is_none();
        if active == filters.retired {
            return false;
        }
        if filters.due
            && !r
                .review_on
                .as_ref()
                .is_some_and(|d| d <= &cutoff.to_string())
        {
            return false;
        }
        if let Some(since) = since {
            let Ok(instant) = DateTime::parse_from_rfc3339(&r.created_at) else {
                return false;
            };
            if instant.with_timezone(&self.timezone).date_naive() < since {
                return false;
            }
        }
        if let Some(search) = &filters.search {
            if !r.content.to_string().contains(search) {
                return false;
            }
        }
        true
    });
    if filters.due {
        records.sort_by(|a, b| {
            a.review_on
                .cmp(&b.review_on)
                .then(a.created_at.cmp(&b.created_at))
                .then(a.id.cmp(&b.id))
        });
    } else {
        records.sort_by(|a, b| b.created_at.cmp(&a.created_at).then(a.id.cmp(&b.id)));
    }
    if offset > records.len() {
        return Err(invalid("cursor offset out of bounds"));
    }
    let end = offset.saturating_add(limit).min(records.len());
    let next = if end < records.len() {
        Some(
            serde_json::to_string(&Cursor {
                database: self.identity.clone(),
                language: lang.into(),
                filters,
                cutoff: cutoff.to_string(),
                offset: end,
            })
            .unwrap(),
        )
    } else {
        None
    };
    Ok(json!({"records": &records[offset..end],"next_cursor":next}))
}

fn queries_pagination_and_context() {
    let (dir, mut db) = setup("Europe/Berlin");
    let mut generated = ["aaaaaa", "bbbbbb", "cccccc", "dddddd"].into_iter();
    db.replace_with_ids("el",request(json!({"ids":[],"replacements":[{"content":{"z":"πήγα","a":{"z":2,"a":1}},"pinned":true,"review":{"in_days":0}},{"content":"Alpha","pinned":true,"review":{"on":"2026-10-16"}},{"content":"alpha","pinned":true,"review":{"in_days":1}},{"content":"other"}]})),||generated.next().unwrap().into()).unwrap();
    let a = "aaaaaa".to_string();
    let b = "bbbbbb".to_string();
    assert_eq!(
        db.get("el", &[b.clone(), a.clone(), b.clone()]).unwrap()["records"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| r["id"].as_str().unwrap())
            .collect::<Vec<_>>(),
        vec!["bbbbbb", "aaaaaa", "bbbbbb"]
    );
    assert_eq!(
        db.get("el", &[a.clone(), "missing".into()])
            .unwrap_err()
            .code,
        "record_missing"
    );
    for limit in [0, 1001] {
        assert!(db.list("el", Filters::default(), limit, None).is_err());
        assert!(db.context(Some("el"), limit).is_err());
        assert!(db.context(None, limit).is_err());
    }
    for limit in [1, 1000] {
        assert!(db.list("el", Filters::default(), limit, None).is_ok());
    }
    assert!(db
        .list(
            "el",
            Filters {
                due: true,
                retired: true,
                ..Default::default()
            },
            20,
            None
        )
        .is_err());
    let sorted = db.list("el", Filters::default(), 20, None).unwrap();
    assert_eq!(
        sorted["records"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| r["id"].as_str().unwrap())
            .collect::<Vec<_>>(),
        vec!["aaaaaa", "bbbbbb", "cccccc", "dddddd"]
    );
    assert!(sorted["next_cursor"].is_null());
    let due = Filters {
        due: true,
        ..Default::default()
    };
    let page = db.list("el", due.clone(), 1, None).unwrap();
    assert_eq!(page["records"][0]["id"], b);
    let cursor = page["next_cursor"].as_str().unwrap();
    let tomorrow = Database::open(&dir.path().join("db"), instant("2026-10-18T12:00:00Z")).unwrap();
    let second = tomorrow
        .list("el", due.clone(), 1000, Some(cursor))
        .unwrap();
    assert_eq!(second["records"].as_array().unwrap().len(), 1);
    assert_eq!(second["records"][0]["id"], a);
    assert!(second["next_cursor"].is_null());
    assert_eq!(
        tomorrow.list("el", due.clone(), 20, None).unwrap()["records"]
            .as_array()
            .unwrap()
            .len(),
        3
    );
    let copy = dir.path().join("copy");
    std::fs::copy(dir.path().join("db"), &copy).unwrap();
    assert!(Database::open(&copy, instant(NOW))
        .unwrap()
        .list("el", due.clone(), 1, Some(cursor))
        .is_ok());
    let (_other, other) = setup("Europe/Berlin");
    assert_eq!(
        other
            .list("el", due.clone(), 1, Some(cursor))
            .unwrap_err()
            .code,
        "invalid_input"
    );
    assert!(db.list("EL", due.clone(), 1, Some(cursor)).is_err());
    assert!(db.list("el", Filters::default(), 1, Some(cursor)).is_err());
    for bad in ["", "{}", "null", "junk"] {
        assert!(db.list("el", due.clone(), 1, Some(bad)).is_err());
    }
    for (search, count) in [
        ("Alpha", 1),
        ("alpha", 1),
        ("πήγα", 1),
        ("\"a\":{\"a\":1,\"z\":2}", 1),
        ("%", 0),
    ] {
        assert_eq!(
            db.list(
                "el",
                Filters {
                    search: Some(search.into()),
                    ..Default::default()
                },
                20,
                None
            )
            .unwrap()["records"]
                .as_array()
                .unwrap()
                .len(),
            count
        );
    }
    let intersection = db
        .list(
            "el",
            Filters {
                due: true,
                since: Some("2026-10-17".into()),
                search: Some("Alpha".into()),
                retired: false,
            },
            20,
            None,
        )
        .unwrap();
    assert_eq!(intersection["records"].as_array().unwrap().len(), 1);
    assert_eq!(intersection["records"][0]["id"], b);
    assert_eq!(
        db.list(
            "el",
            Filters {
                since: Some("2026-10-18".into()),
                ..Default::default()
            },
            20,
            None
        )
        .unwrap()["records"],
        json!([])
    );
    let bytes = std::fs::read(dir.path().join("db")).unwrap();
    let ctx = db.context(Some("el"), 1).unwrap();
    assert_eq!(ctx["pinned"].as_array().unwrap().len(), 3);
    assert_eq!(ctx["pinned"][0]["id"], a);
    assert_eq!(ctx["recent"]["records"].as_array().unwrap().len(), 1);
    assert_eq!(ctx["due"], page);
    assert!(ctx["recent"]["next_cursor"].is_string());
    assert_eq!(ctx["language"], "el");
    assert_eq!(ctx["timezone"], "Europe/Berlin");
    assert_eq!(ctx["today"], "2026-10-17");
    assert_eq!(ctx["now"], "2026-10-17T12:00:00.000000000Z");
    assert_eq!(std::fs::read(dir.path().join("db")).unwrap(), bytes);
    let unselected = db.context(None, 20).unwrap();
    assert_eq!(unselected.as_object().unwrap().len(), 4);
    for key in ["language", "pinned", "due", "recent"] {
        assert!(unselected.get(key).is_none());
    }
    db.replace("el", request(json!({"ids":[a],"replacements":[]})))
        .unwrap();
    let retired = db
        .list(
            "el",
            Filters {
                retired: true,
                ..Default::default()
            },
            20,
            None,
        )
        .unwrap();
    assert_eq!(retired["records"].as_array().unwrap().len(), 1);
    assert_eq!(retired["records"][0]["id"], a);
    assert_eq!(
        db.context(Some("el"), 1).unwrap()["pinned"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
}

fn default_page_size_is_twenty_for_list_and_context() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("db");
    let p = p.to_str().unwrap();
    success(run(&["init", p, "--timezone", "UTC"], None));
    let input=json!({"ids":[],"replacements":(0..25).map(|i|json!({"content":i,"pinned":true,"review":{"in_days":0}})).collect::<Vec<_>>()}).to_string();
    success(run(
        &["--db", p, "--language", "el", "replace", "--file", "-"],
        Some(input.as_bytes()),
    ));
    let list = success(run(&["--db", p, "--language", "el", "list"], None));
    assert_eq!(list["records"].as_array().unwrap().len(), 20);
    assert!(list["next_cursor"].is_string());
    let ctx = success(run(&["--db", p, "--language", "el", "context"], None));
    for section in ["due", "recent"] {
        assert_eq!(ctx[section]["records"].as_array().unwrap().len(), 20);
        assert!(ctx[section]["next_cursor"].is_string());
    }
    assert_eq!(ctx["pinned"].as_array().unwrap().len(), 25);
}

use chrono::{DateTime, Utc};
use language_lab::{Database, Filters, Replacement, Review};
use serde_json::{json, Value};
use tempfile::TempDir;
fn instant(s: &str) -> DateTime<Utc> {
    s.parse().unwrap()
}
const NOW: &str = "2026-10-17T12:00:00Z";
fn setup(zone: &str) -> (TempDir, Database) {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("db");
    Database::init(&p, zone).unwrap();
    let db = Database::open(&p, instant(NOW)).unwrap();
    (dir, db)
}
fn request(v: Value) -> Replacement {
    serde_json::from_value(v).unwrap()
}
fn add(db: &mut Database, lang: &str, content: Value) -> String {
    db.replace(
        lang,
        request(json!({"ids":[],"replacements":[{"content":content}]})),
    )
    .unwrap()["created"][0]
        .as_str()
        .unwrap()
        .into()
}
fn record(db: &Database, lang: &str, id: &str) -> Value {
    db.get(lang, &[id.into()]).unwrap()["records"][0].clone()
}
fn review(days: u64) -> Option<Review> {
    Some(Review {
        in_days: Some(days),
        on: None,
    })
}

use serde_json::{json, Value};
use std::{
    io::Write,
    process::{Command, Output, Stdio},
};
fn run(args: &[&str], input: Option<&[u8]>) -> Output {
    let mut c = Command::new(env!("CARGO_BIN_EXE_language-lab"));
    c.args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = c.spawn().unwrap();
    if let Some(input) = input {
        child.stdin.take().unwrap().write_all(input).unwrap();
    }
    child.wait_with_output().unwrap()
}
fn success(out: Output) -> Value {
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(out.stderr.is_empty());
    serde_json::from_slice(&out.stdout).unwrap()
}
fn failure(out: Output, code: &str) {
    assert!(!out.status.success());
    assert!(out.stdout.is_empty());
    let v: Value = serde_json::from_slice(&out.stderr).unwrap();
    assert_eq!(v["error"]["code"], code);
    assert!(v["error"]["message"].is_string());
}
